Source code in <code>rgrow-python/rgrow/__init__.py</code> <pre><code>@attrs.define(auto_attribs=True)
class Bond:
    name: str
    strength: float

    @staticmethod
    def _conv(a: "Bond | Any", *args: Any, **kwargs: Any) -&gt; "Bond":
        if isinstance(a, Bond):
            return a
        elif isinstance(a, dict):
            return Bond(**a)
        elif isinstance(a, tuple):
            return Bond(*a)
        else:
            return Bond(a, *args, **kwargs)  # type: ignore
